import { h, type FunctionalComponent } from "vue";

// Icons are CSS masks generated by UnoCSS presetIcons, not bundled SVG components.
// Literal utility names are extracted at build time (including dynamic menu icons).
function icon(className: string): FunctionalComponent<{ size?: number }> {
  return (props, { attrs }) =>
    h("span", {
      ...attrs,
      "aria-hidden": "true",
      class: ["ui-icon", className, attrs.class],
      style: {
        width: `${props.size || 20}px`,
        height: `${props.size || 20}px`,
      },
    });
}
